const item = $input.first().json;
const body = item.body || item;
const type = String(item.messageType || body.type || body.metadata?.message?.mediaType || 'text').toLowerCase();
const mediaUrl = body.mediaUrl || body.metadata?.message?.mediaUrl || '';
const content = String(item.content || body.content || body.text || '').trim();
const lower = content.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const dmsRegex = new RegExp("maps\\.google|\\d{1,3}\\s*(?:\\u00B0|\\u00BA|\\?)\\s*\\d{1,2}['?]");
return [{
  json: {
    ...item,
    roteamento_conteudo: {
      type,
      mediaUrl,
      isText: type === 'text' && content.length > 0,
      isAudio: type.includes('audio'),
      isImage: type.includes('image'),
      isDocument: type.includes('document') || /\.pdf($|\?)/i.test(mediaUrl),
      isLocationLike: dmsRegex.test(content) || Boolean(body.location || body.metadata?.message?.dataJson?.message?.locationMessage),
      wantsMenu: /cardapio|menu|sabores|opcoes/.test(lower),
      wantsHuman: /humano|atendente|pessoa|falar com alguem/.test(lower)
    }
  }
}];

const item = $input.first().json;
const body = item.body || item;
const backendUrl = String(body.metadata?.backendUrl || 'https://vib.correacloud.com.br/backend').replace(/\/+$/, '');
const mediaUrl = body.mediaUrl || body.metadata?.message?.mediaUrl || '';
const absoluteMediaUrl = mediaUrl && String(mediaUrl).startsWith('http') ? mediaUrl : (mediaUrl ? `${backendUrl}/public/${mediaUrl}` : '');
const location = body.metadata?.message?.dataJson?.message?.locationMessage || body.message?.dataJson?.message?.locationMessage || body.location || null;
return [{
  json: {
    ...item,
    midia_processada: {
      absoluteMediaUrl,
      hasMedia: Boolean(absoluteMediaUrl),
      mediaType: item.roteamento_conteudo?.type || 'text',
      location
    }
  }
}];

const item = $input.first().json;
const body = item.body || item;
const ticketId = item.dados_coletados?.ticket_id || body.ticket_id || body.metadata?.ticketId || body.metadata?.ticket_id || 'sem-ticket';
const companyId = '6d558f61-4f94-40aa-b96c-b8d6e8c38523';
return [{
  json: {
    ...item,
    memoria_operacional: {
      companyId,
      ticketId,
