const item = $input.first().json;
return [{
  json: {
    ...item,
    ferramentas_operacionais: {
      saas: {
        context: '/integrations/restaurants/:companyId/context',
        menu: '/integrations/restaurants/:companyId/menu',
        drafts: '/integrations/restaurants/:companyId/drafts/:draftKey',
        orders: '/integrations/restaurants/:companyId/orders',
