      },
      ticketz: {
        sendOrNote: '/integrations/webhook'
      },
      enabledInOrchestrator: true
    }
  }
}];

const config = $input.first().json;
const body = config.body || {};
const companyId = '6d558f61-4f94-40aa-b96c-b8d6e8c38523';
const publicMenuBase = 'https://saas.correacloud.com.br/cardapio/pizzaria-big-burguer';
const rawSaasBase = String(config.saasBase || 'https://saas.correacloud.com.br/api').replace(/\/+$/, '');
const saasBase = rawSaasBase.endsWith('/api') ? rawSaasBase : `${rawSaasBase}/api`;
const secret = String(config.secret || '');
const customer = body.metadata?.from || body.customer || {};
const text = String(body.content || body.text || body.message?.content || '').trim();

const httpRequest = this.helpers.httpRequest.bind(this.helpers);

function normalize(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

function cleanPhone(value) {
  return String(value || '').replace(/\D/g, '');
}

function customerName() {
  const name = String(customer.name || customer.pushname || body.contact_name || body.name || '').trim();
  if (!name || normalize(name) === 'cliente') return '';
  return name;
}

function customerPhone() {
  return cleanPhone(customer.number || customer.phone || customer.whatsapp || body.phone || body.customer_phone || '');
}

function buildMenuLink(extra = {}) {
  const params = [];
  const name = customerName();
  const phone = customerPhone();
  if (name) params.push(['name', name]);
  if (phone) params.push(['phone', phone]);
  for (const [key, value] of Object.entries(extra)) {
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      params.push([key, String(value)]);
    }
  }
  const qs = params
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join('&');
  return qs ? `${publicMenuBase}?${qs}` : publicMenuBase;
}

async function loadContext() {
  try {
    return await httpRequest({
      method: 'GET',
      url: `${saasBase}/integrations/restaurants/${companyId}/context`,
      headers: { 'x-webhook-secret': secret },
      json: true,
      timeout: 8000
    });
  } catch (error) {
    return { company: { acceptOrders: true, deliveryFeeDefault: 4, preparationTimeMinutes: 35 }, contextError: error.message };
  }
}

function firstName() {
  return customerName().split(/\s+/).filter(Boolean)[0] || '';
}

function greeting() {
  const name = firstName();
  return name ? `Oi, ${name}!` : 'Oi!';
}

function orderMessage(company) {
  const link = buildMenuLink();
  return [
    `${greeting()} Para fazer seu pedido, acesse nosso cardapio:`,
    link,
    '',
    'Por la voce escolhe pizzas, sabores, bebidas, entrega/retirada e pagamento.',
    'Assim que enviar, a loja recebe no painel e confirma por aqui.'
  ].join(String.fromCharCode(10));
}

function statusMessage() {
  const link = buildMenuLink({ view: 'orders' });
  return [
    `${greeting()} Para acompanhar seus pedidos, acesse:`,
    link,
    '',
    'Use o mesmo WhatsApp que informou no pedido.'
  ].join(String.fromCharCode(10));
}

function isWithinBusinessHours(contextPayload) {
  const source = contextPayload.context || contextPayload;
  const timezone = source.settings?.timezone || 'America/Sao_Paulo';
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: timezone,
    weekday: 'short',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23'
  })
    .formatToParts(new Date())
    .reduce((acc, part) => ({ ...acc, [part.type]: part.value }), {});
  const weekMap = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  const dayOfWeek = weekMap[parts.weekday] ?? new Date().getDay();
  const currentTime = `${parts.hour || '00'}:${parts.minute || '00'}`;
  const todaysHours = (source.businessHours || []).find(hour =>
    Number(hour.dayOfWeek) === dayOfWeek && String(hour.type || 'normal') === 'normal'
  );
  return Boolean(
    todaysHours &&
    !todaysHours.isClosed &&
    todaysHours.openTime &&
    todaysHours.closeTime &&
    currentTime >= todaysHours.openTime &&
    currentTime <= todaysHours.closeTime
  );
}

function closedMessage() {
  return [
    `${greeting()} No momento ainda nao estamos funcionando.`,
    '',
    'Horario de funcionamento:',
    'Quinta-feira: 18:00 as 22:30',
    'Sexta-feira: 18:00 as 22:30',
    'Sabado: 18:00 as 23:00',
    'Domingo: 18:00 as 23:00'
  ].join('\n');
}

function humanMessage(company) {
  return [
    `${greeting()} Vou chamar alguem da loja para te ajudar.`,
    company?.acceptOrders === false
      ? 'A loja esta fechada para novos pedidos no momento.'
      : `Se quiser adiantar o pedido, o cardapio esta aqui: ${buildMenuLink()}`
  ].join(String.fromCharCode(10));
}

const context = await loadContext();
const company = context.company || {};
const normalized = normalize(text);
const incomingType = String(body.type || body.metadata?.message?.mediaType || 'text').toLowerCase();

const wantsHuman = /\b(humano|atendente|pessoa|falar com alguem|falar com atendente|suporte)\b/.test(normalized);
const wantsStatus = /\b(cade|cadê|status|acompanhar|andamento|meu pedido|pedido chegou|saiu|saiu pra entrega|saiu para entrega|demora|previsao|previsão|pronto)\b/.test(normalized);
const isMedia = incomingType.includes('audio') || incomingType.includes('image') || incomingType.includes('document') || Boolean(body.mediaUrl || body.metadata?.message?.mediaUrl);

let responseText;
let note;

if (wantsHuman) {
  responseText = humanMessage(company);
  note = `Cliente pediu atendimento humano. Mensagem: ${text || incomingType}`;
} else if (company.acceptOrders === false || !isWithinBusinessHours(context)) {
  responseText = closedMessage();
} else if (wantsStatus) {
  responseText = statusMessage();
} else if (isMedia) {
  responseText = `${greeting()} recebi sua midia. Para pedido, use o cardapio: ${buildMenuLink()}\nSe quiser falar com a loja, responda: atendente.`;
} else {
  responseText = orderMessage(company);
}

const output = [{
  type: 'message',
  text: responseText,
  ...(note ? { note } : {})
}];

return [{
  json: {
    output,
    actionResults: [],
    mode: 'public_checkout_link',
    publicMenuUrl: buildMenuLink(),
    statusUrl: buildMenuLink({ view: 'orders' }),
    storeOpen: company.acceptOrders !== false && isWithinBusinessHours(context)
  }
}];

const item = $input.first().json;
const output = Array.isArray(item.output) ? item.output : [];
return [{ json: { ...item, output } }];

const item = $input.first().json;
let output = Array.isArray(item.output) ? item.output : [];
if (!output.length) {
  output = [{ type: 'message', text: 'Recebi sua mensagem. Vou seguir com seu atendimento por aqui.' }];
}
return [{ json: { ...item, output } }];
